diff:
--- a/src/main/java/clinic/auth/RoleGuard.java
+++ b/src/main/java/clinic/auth/RoleGuard.java
@@ -10,13 +10,26 @@ public class RoleGuard {

     private static final String VET = "vet";

-    public boolean canOpenCard(Token token) {
-        return token != null;
+    public boolean canOpenCard(Token token) {
+        if (token == null || token.isExpired()) {
+            return false;
+        }
+
+        String role = token.claim("role");
+
+        return role == VET;
+    }
+
+    public boolean canEditCard(Token token) {
+        return canOpenCard(token) && token.claim("scope").contains("write");
     }

     public String describe(Token token) {
         return token == null ? "anonymous" : token.claim("role");
     }
 }
